"""GIVE roles, possession and NPC request lifetime: offline typed excerpts."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True
p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0x8321,0x8329,'data','Modello GIVE: TO facoltativo e destinatario anticipato senza TO'),(0xB405,0xB483,'code','Ruoli semantici: oggetto e destinatario dai due gruppi fisici'),(0xB280,0xB2B7,'code','Selezione della coppia: un solo destinatario valido per oggetto'),(0xC7E4,0xC7F9,'code','Classe A: oggetto percepibile posseduto dall’attore corrente'),(0xC814,0xC821,'code','Classe D: destinatario percepibile di categoria persona'),(0xC8C6,0xC8EF,'code','Capienza del destinatario e peso complessivo dell’oggetto'),(0xD275,0xD29D,'code','Possesso ricorsivo: risalita dei genitori rispetto ad A036'),(0xDF02,0xDF06,'data','Header GIVE: classi A/D, luce, costo1 e predicato DF24'),(0xDF06,0xDF24,'code','Consegna: cambia genitore e propaga la stanza ai contenuti'),(0xDF24,0xDF2E,'code','Predicato GIVE: confronto peso e capacità dei due riferimenti'),(0xB936,0xB98C,'code','Richieste NPC: il cursore si salva soltanto dopo risoluzione riuscita'),(0xB9AC,0xB9FA,'code','Rifiuto o ALL esaurito: avanza e libera la richiesta'),(0xA7D0,0xA7EA,'code','Nome YOU: eccezione alla maiuscola dei nomi propri')]
notes={0x8321:'Record lessicale di8 byte, non istruzioni: il bit5 del modo ricomposto A01E inverte i gruppi senza preposizione. GIVE WATSON MONEY e GIVE ME MY MONEY anticipano il destinatario. MY e ME sono alias di YOUR e YOU; il possessivo resta una proprietà lessicale dell’oggetto, non viene cambiato dal trasferimento.',0xB405:'Non indovinare il ruolo dai tipi dei nomi: contano modello e preposizioni. Le copie semantiche sono distinte dagli offset fisici del nodo08/12, necessari per continuazioni, errori e arena.',0xB421:'Nessuna preposizione: legge il modo A01E. GIVE passa da B445 e seleziona il secondo gruppo fisico come oggetto. Con ALL il secondo gruppo può essere vuoto.',0xB445:'Inversione del bit5, poi scelta delle coppie di offset1208 oppure0812. Applicare una volta sola, anche durante ALL.',0xB474:'Copia esattamente6 byte: nome e due qualificatori; non modificare la sintassi originale.',0xB29A:'Senza destinatario esplicito contano anche Holmes e Watson: con il solo denaro due partner validi fanno fallire GIVE/GIVE ALL. Non escludere automaticamente il soggetto. Il primo oggetto sopravvive soltanto se esiste esattamente un destinatario accettabile. ALL conserva l’ordine crescente degli ID, e un NPC esegue una consegna per turno.',0xC7F0:'D275 controlla possesso transitivo dell’attore A036: una richiesta non può regalare un oggetto posseduto da Holmes come se fosse di Watson.',0xC81B:'Il destinatario è una persona percepibile; non esclude automaticamente il soggetto. GIVE MONEY TO ME può riuscire se il predicato di capacità lo permette.',0xC8C6:'Somma peso ricorsivo, gestisce i limiti originali a8 bit e confronta la capacità. Non usare la sola dimensione del contenitore.',0xD288:'Risalita dei genitori fino all’attore corrente; non confronta il qualificatore YOUR. Quindi your money mantiene il nome mentre cambia possessore.',0xDF02:'6A 1D 24 DF: due classi A/D, luce, costo1, puntatore al predicato DF24. Non disassemblare questi quattro byte come CPU.',0xDF11:'Scrive il destinatario nel genitore dell’oggetto; DF17 copia la sua stanza e D249 aggiorna i discendenti. GIVE MONEY trasferisce il record intero, senza accorpare pence o eseguire PAY.',0xDF24:'Passa i due ID al controllo C8C6; lo stesso predicato vale per Holmes e per gli altri attori.',0xB969:'Se B191 fallisce, salta a B9B4 PRIMA degli store del cursore B973/B976. Non sporcare un record liberato con un iteratore mai accettato.',0xB97F:'Modo0 avanza subito il nodo; ALL lo conserva per il prossimo turno. Nessuna risposta speciale di Watson per la restituzione.',0xB9B4:'Richiesta normale fallita: scarta il suffisso. ALL esaurito: azzera il flag e passa al nodo successivo, senza buttare via la richiesta intera.',0xA7D9:'Noun09EE (YOU): anche col bit di nome proprio non imposta la maiuscola. La frase termina con to you, non to You.'}
lines=['; Sherlock: GIVE, richieste e possesso. Header e modelli sono dati tipizzati.'];count=total=0
for a,b,k,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {k.upper()}: {label}'];at=a
 while at<b:
  if at in notes:lines.append('; '+notes[at])
  if k=='code':op,n=disassemble(m,at);count+=1
  else:n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  assert at+n<=b,(hex(at),op)
  assert bytes(asm.assemble(op,at))==m[at:at+n],(hex(at),op)
  lines.append(f'    {op:<36} ; ${at:04X} {m[at:at+n].hex(" ")}');total+=n;at+=n
out=p/'sherlock-js/results/npc-handover';out.mkdir(exist_ok=True)
(out/'npc-handover.asm').write_text('\n'.join(lines)+'\n')
(out/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=126)for a,b,k,l in regions]),indent=2)+'\n');print(count,total)
